package com.ezbarrows;

import com.google.common.collect.ImmutableMap;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

import java.util.Arrays;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;

@Getter
@RequiredArgsConstructor
public enum BarrowsBrother
{
	AHRIM("Ahrim", 98, new WorldPoint(3566, 3289, 0), ObjectID.BARROW_AHRIM_SARCOPHAGUS, VarbitID.BARROWS_KILLED_AHRIM),
	DHAROK("Dharok", 115, new WorldPoint(3575, 3298, 0), ObjectID.BARROW_DHAROK_SARCOPHAGUS, VarbitID.BARROWS_KILLED_DHAROK),
	GUTHAN("Guthan", 115, new WorldPoint(3577, 3283, 0), ObjectID.BARROW_GUTHAN_SARCOPHAGUS, VarbitID.BARROWS_KILLED_GUTHAN),
	KARIL("Karil", 98, new WorldPoint(3566, 3275, 0), ObjectID.BARROW_KARIL_SARCOPHAGUS, VarbitID.BARROWS_KILLED_KARIL),
	TORAG("Torag", 115, new WorldPoint(3553, 3283, 0), ObjectID.BARROW_TORAG_SARCOPHAGUS, VarbitID.BARROWS_KILLED_TORAG),
	VERAC("Verac", 115, new WorldPoint(3557, 3298, 0), ObjectID.BARROW_VERAC_SARCOPHAGUS, VarbitID.BARROWS_KILLED_VERAC);

	private static final Map<Integer, BarrowsBrother> BY_SARCOPHAGUS = ImmutableMap.copyOf(
		Arrays.stream(values()).collect(Collectors.toMap(BarrowsBrother::getSarcophagusId, Function.identity())));

	private final String displayName;
	private final int combatLevel;
	// Centre of the brother's mound on the surface
	private final WorldPoint mound;
	private final int sarcophagusId;
	private final int killedVarbit;

	static BarrowsBrother fromSarcophagus(int objectId)
	{
		return BY_SARCOPHAGUS.get(objectId);
	}

	// Image of the brother, relative to the plugin's resources
	String getPortraitPath()
	{
		return "brothers/" + name().toLowerCase() + ".png";
	}

	// Brothers are worth 2 more reward points than their combat level
	int getRewardPoints()
	{
		return combatLevel + 2;
	}
}

package com.ezbarrows;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

import java.awt.Color;

@ConfigGroup("ezbarrows")
public interface EzBarrowsConfig extends Config
{
	@ConfigItem(
		keyName = "hideKilled",
		name = "Hide Killed Brothers",
		description = "Hide the portrait once that brother has been killed this run.",
		position = 1
	)
	default boolean hideKilled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBrotherNames",
		name = "Show Brother Names",
		description = "Name each mound: green if alive, red if killed, blue once found to be the tunnel.",
		position = 2
	)
	default boolean showBrotherNames()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPath",
		name = "Show Tunnel Path",
		description = "Draw the shortest route to the chest through the doors you can open.",
		position = 3
	)
	default boolean showPath()
	{
		return true;
	}

	@ConfigItem(
		keyName = "pathColour",
		name = "Tunnel Path Colour",
		description = "Colour of the route line in the tunnels.",
		position = 4
	)
	default Color pathColour()
	{
		return Color.CYAN;
	}

	@ConfigItem(
		keyName = "showPotential",
		name = "Show Reward Potential",
		description = "Show your reward potential and what's left to kill to reach your cap.",
		position = 5
	)
	default boolean showPotential()
	{
		return true;
	}

	@Range(max = RewardPotential.MAX_POINTS)
	@ConfigItem(
		keyName = "pointsCap",
		name = "Points Cap",
		description = "Reward points to get as close to as possible without going over, out of 1012. 874 is 6 brothers, 2 skeletons and 1 bloodworm; 880 is 86.95%.",
		position = 6
	)
	default int pointsCap()
	{
		return 874;
	}

	@ConfigItem(
		keyName = "highlightMonsters",
		name = "Highlight Target Monsters",
		description = "Outline tunnel monsters you still need to kill to get closest to your cap.",
		position = 7
	)
	default boolean highlightMonsters()
	{
		return true;
	}

	@ConfigItem(
		keyName = "monsterColour",
		name = "Target Monster Colour",
		description = "Colour of the outline on target monsters.",
		position = 8
	)
	default Color monsterColour()
	{
		return new Color(0x3399ff);
	}

	@ConfigItem(
		keyName = "highlightChest",
		name = "Highlight Chest When Ready",
		description = "Outline the chest once every brother is dead and no more kills would get you closer to your cap.",
		position = 9
	)
	default boolean highlightChest()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chestColour",
		name = "Ready Chest Colour",
		description = "Colour of the outline on the chest when it's ready to loot.",
		position = 10
	)
	default Color chestColour()
	{
		return Color.GREEN;
	}
}

package com.ezbarrows;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;

public class EzBarrowsHighlightOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 2;

	private final Client client;
	private final EzBarrowsPlugin plugin;
	private final EzBarrowsConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	@Inject
	EzBarrowsHighlightOverlay(Client client, EzBarrowsPlugin plugin, EzBarrowsConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Map<RewardPotential.TunnelMonster, Integer> kills = plugin.getSuggestedKills();
		if (config.highlightMonsters() && !kills.isEmpty())
		{
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				RewardPotential.TunnelMonster monster = RewardPotential.TunnelMonster.fromNpc(npc.getName(), npc.getCombatLevel());
				if (monster != null && kills.containsKey(monster) && !npc.isDead())
				{
					outlineRenderer.drawOutline(npc, OUTLINE_WIDTH, config.monsterColour(), OUTLINE_FEATHER);
				}
			}
		}

		GameObject chest = plugin.getChest();
		if (config.highlightChest() && plugin.isReadyToLoot() && chest != null)
		{
			outlineRenderer.drawOutline(chest, OUTLINE_WIDTH, config.chestColour(), OUTLINE_FEATHER);
		}
		return null;
	}
}

package com.ezbarrows;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;

public class EzBarrowsMoundOverlay extends Overlay
{
	// Height above the mound to draw the name, in local units
	private static final int NAME_Z_OFFSET = 50;
	private static final Color ALIVE_COLOUR = Color.GREEN;
	private static final Color KILLED_COLOUR = Color.RED;
	private static final Color TUNNEL_COLOUR = new Color(0x3399ff);

	private final Client client;
	private final EzBarrowsPlugin plugin;
	private final EzBarrowsConfig config;

	@Inject
	EzBarrowsMoundOverlay(Client client, EzBarrowsPlugin plugin, EzBarrowsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (!config.showBrotherNames() || player == null
			|| player.getWorldLocation().getRegionID() != EzBarrowsPlugin.SURFACE_REGION_ID)
		{
			return null;
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		for (BarrowsBrother brother : BarrowsBrother.values())
		{
			LocalPoint mound = LocalPoint.fromWorld(client.getTopLevelWorldView(), brother.getMound());
			if (mound == null)
			{
				continue;
			}

			Point location = Perspective.getCanvasTextLocation(client, graphics, mound, brother.getDisplayName(), NAME_Z_OFFSET);
			if (location != null)
			{
				boolean killed = client.getVarbitValue(brother.getKilledVarbit()) != 0;
				OverlayUtil.renderTextLocation(graphics, location, brother.getDisplayName(),
					nameColour(killed, brother == plugin.getTunnelBrother()));
			}
		}
		return null;
	}

	static Color nameColour(boolean killed, boolean tunnel)
	{
		if (killed)
		{
			return KILLED_COLOUR;
		}
		return tunnel ? TUNNEL_COLOUR : ALIVE_COLOUR;
	}
}

package com.ezbarrows;

import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;

public class EzBarrowsOverlay extends Overlay
{
	// Height above the tile to draw the portrait, in local units
	private static final int PORTRAIT_Z_OFFSET = 150;

	private final Client client;
	private final EzBarrowsPlugin plugin;
	private final EzBarrowsConfig config;
	private final Map<BarrowsBrother, BufferedImage> portraits = new EnumMap<>(BarrowsBrother.class);

	@Inject
	EzBarrowsOverlay(Client client, EzBarrowsPlugin plugin, EzBarrowsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		for (Map.Entry<GameObject, BarrowsBrother> entry : plugin.getReachableSarcophagi().entrySet())
		{
			BarrowsBrother brother = entry.getValue();
			if (config.hideKilled() && client.getVarbitValue(brother.getKilledVarbit()) != 0)
			{
				continue;
			}

			BufferedImage portrait = portraits.computeIfAbsent(brother, EzBarrowsOverlay::loadPortrait);
			Point location = Perspective.getCanvasImageLocation(client, entry.getKey().getLocalLocation(), portrait, PORTRAIT_Z_OFFSET);
			if (location != null)
			{
				graphics.drawImage(portrait, location.getX(), location.getY(), null);
			}
		}
		return null;
	}

	static BufferedImage loadPortrait(BarrowsBrother brother)
	{
		return ImageUtil.loadImageResource(EzBarrowsOverlay.class, brother.getPortraitPath());
	}
}

package com.ezbarrows;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;

public class EzBarrowsPathOverlay extends Overlay
{
	private static final BasicStroke PATH_STROKE = new BasicStroke(3, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);

	private final Client client;
	private final EzBarrowsPlugin plugin;
	private final EzBarrowsConfig config;

	@Inject
	EzBarrowsPathOverlay(Client client, EzBarrowsPlugin plugin, EzBarrowsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Point> path = plugin.getPath();
		if (path.size() < 2)
		{
			return null;
		}

		WorldView worldView = client.getTopLevelWorldView();
		graphics.setStroke(PATH_STROKE);
		graphics.setColor(config.pathColour());

		Point previous = null;
		for (Point tile : path)
		{
			LocalPoint localPoint = LocalPoint.fromScene(tile.getX(), tile.getY(), worldView);
			Point canvas = Perspective.localToCanvas(client, localPoint, worldView.getPlane());
			if (previous != null && canvas != null)
			{
				graphics.drawLine(previous.getX(), previous.getY(), canvas.getX(), canvas.getY());
			}
			previous = canvas;
		}
		return null;
	}
}

package com.ezbarrows;

import com.ezbarrows.RewardPotential.TunnelMonster;
import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import java.util.stream.Collectors;

@PluginDescriptor(
	name = "EzBarrows",
	description = "Barrows helper: brother portraits on sarcophagi, brother names on mounds, a reward potential tracker and the tunnel route to the chest",
	tags = {"barrows", "pvm", "crypt", "tunnel", "path", "mound", "brothers", "reward", "potential", "chest"}
)
public class EzBarrowsPlugin extends Plugin
{
	private static final Set<Integer> CHEST_IDS = ImmutableSet.of(
		ObjectID.BARROWS_STONE_CHEST, ObjectID.BARROWS_STONE_CHEST_CLOSED, ObjectID.BARROWS_STONE_CHEST_OPEN);
	private static final String HIDDEN_TUNNEL_TEXT = "hidden tunnel";
	static final int SURFACE_REGION_ID = 14131;
	// Crypts and tunnels
	static final int UNDERGROUND_REGION_ID = 14231;

	@Inject
	private Client client;

	@Inject
	private EzBarrowsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private EzBarrowsOverlay overlay;

	@Inject
	private EzBarrowsPathOverlay pathOverlay;

	@Inject
	private EzBarrowsMoundOverlay moundOverlay;

	@Inject
	private EzBarrowsPotentialOverlay potentialOverlay;

	@Inject
	private EzBarrowsHighlightOverlay highlightOverlay;

	private final Map<GameObject, BarrowsBrother> sarcophagi = new HashMap<>();

	@Getter(AccessLevel.PACKAGE)
	private Map<GameObject, BarrowsBrother> reachableSarcophagi = Collections.emptyMap();

	@Getter(AccessLevel.PACKAGE)
	private List<Point> path = Collections.emptyList();

	// Kept across scene loads until the chest is looted
	@Getter(AccessLevel.PACKAGE)
	private BarrowsBrother tunnelBrother;
	private int lastKilledCount;

	private final Set<TileObject> doors = new HashSet<>();
	// Remembered so doors still count as unlocked while opening
	private final Set<Point> unlockedDoorTiles = new HashSet<>();
	@Getter(AccessLevel.PACKAGE)
	private GameObject chest;

	// Tunnel monsters still to kill to get closest to the cap
	@Getter(AccessLevel.PACKAGE)
	private Map<TunnelMonster, Integer> suggestedKills = Collections.emptyMap();
	@Getter(AccessLevel.PACKAGE)
	private boolean readyToLoot;
	private int suggestedRoom = Integer.MIN_VALUE;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(pathOverlay);
		overlayManager.add(moundOverlay);
		overlayManager.add(potentialOverlay);
		overlayManager.add(highlightOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(pathOverlay);
		overlayManager.remove(moundOverlay);
		overlayManager.remove(potentialOverlay);
		overlayManager.remove(highlightOverlay);
		reset();
		tunnelBrother = null;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		BarrowsBrother brother = BarrowsBrother.fromSarcophagus(object.getId());
		if (brother != null)
		{
			sarcophagi.put(object, brother);
		}
		else if (CHEST_IDS.contains(object.getId()))
		{
			chest = object;
		}
		else if (isDoor(object.getId()))
		{
			doors.add(object);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();
		sarcophagi.remove(object);
		doors.remove(object);
		if (object == chest)
		{
			chest = null;
		}
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		if (isDoor(event.getWallObject().getId()))
		{
			doors.add(event.getWallObject());
		}
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		doors.remove(event.getWallObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			reset();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Looting the chest ends the run
		if (event.getGroupId() == InterfaceID.BARROWS_REWARD)
		{
			tunnelBrother = null;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		CollisionData[] collisionMaps = worldView.getCollisionMaps();
		if (player == null || collisionMaps == null || !isAtBarrows(player))
		{
			reachableSarcophagi = Collections.emptyMap();
			path = Collections.emptyList();
			clearRewardPlan();
			return;
		}

		int[][] flags = collisionMaps[worldView.getPlane()].getFlags();
		Point start = toScenePoint(player.getLocalLocation());
		reachableSarcophagi = findReachableSarcophagi(flags, start, worldView.getPlane());
		path = config.showPath() ? findPathToChest(flags, start, worldView.getPlane()) : Collections.emptyList();
		updateTunnelBrother();
		updateRewardPlan();
	}

	private void updateRewardPlan()
	{
		List<BarrowsBrother> alive = Arrays.stream(BarrowsBrother.values())
			.filter(brother -> client.getVarbitValue(brother.getKilledVarbit()) == 0)
			.collect(Collectors.toList());
		int points = RewardPotential.currentPoints(client.getVarbitValue(VarbitID.BARROWS_KILLED_MONSTER),
			BarrowsBrother.values().length - alive.size());
		// Remaining brothers are always counted; only tunnel monsters are fitted under the cap
		int room = config.pointsCap() - points - alive.stream().mapToInt(BarrowsBrother::getRewardPoints).sum();
		// Only search again when the room left changes
		if (room != suggestedRoom)
		{
			suggestedRoom = room;
			suggestedKills = RewardPotential.killsToCap(room);
		}
		readyToLoot = isReadyToLoot(alive.size(), suggestedKills);
	}

	// Nothing left that would get closer to the cap
	static boolean isReadyToLoot(int brothersAlive, Map<TunnelMonster, Integer> suggestedKills)
	{
		return brothersAlive == 0 && suggestedKills.isEmpty();
	}

	private void clearRewardPlan()
	{
		suggestedKills = Collections.emptyMap();
		suggestedRoom = Integer.MIN_VALUE;
		readyToLoot = false;
	}

	private void updateTunnelBrother()
	{
		Predicate<BarrowsBrother> isKilled = brother -> client.getVarbitValue(brother.getKilledVarbit()) != 0;
		int killedCount = (int) Arrays.stream(BarrowsBrother.values()).filter(isKilled).count();
		// Kills only drop back to zero when a new run starts
		if (killedCount == 0 && lastKilledCount > 0)
		{
			tunnelBrother = null;
		}
		lastKilledCount = killedCount;

		// The hidden tunnel prompt only appears in the tunnel brother's crypt
		if (isHiddenTunnelPromptOpen() && reachableSarcophagi.size() == 1)
		{
			tunnelBrother = reachableSarcophagi.values().iterator().next();
		}
		if (tunnelBrother == null)
		{
			tunnelBrother = onlyBrotherAlive(isKilled);
		}
	}

	private boolean isHiddenTunnelPromptOpen()
	{
		if (mentionsHiddenTunnel(client.getWidget(InterfaceID.Objectbox.TEXT))
			|| mentionsHiddenTunnel(client.getWidget(InterfaceID.Messagebox.TEXT)))
		{
			return true;
		}
		// Yes/no menus put the question in the first option line
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (options == null || options.isHidden() || options.getDynamicChildren() == null)
		{
			return false;
		}
		return Arrays.stream(options.getDynamicChildren()).anyMatch(EzBarrowsPlugin::mentionsHiddenTunnel);
	}

	private static boolean mentionsHiddenTunnel(Widget widget)
	{
		return widget != null && !widget.isHidden() && widget.getText() != null
			&& mentionsHiddenTunnel(widget.getText());
	}

	// Long dialogue text can be wrapped with <br> between any two words
	static boolean mentionsHiddenTunnel(String text)
	{
		return text.replace("<br>", " ").toLowerCase().contains(HIDDEN_TUNNEL_TEXT);
	}

	// With five brothers killed, the one left must be in the tunnel
	static BarrowsBrother onlyBrotherAlive(Predicate<BarrowsBrother> isKilled)
	{
		List<BarrowsBrother> alive = Arrays.stream(BarrowsBrother.values())
			.filter(isKilled.negate())
			.collect(Collectors.toList());
		return alive.size() == 1 ? alive.get(0) : null;
	}

	// Crypts are walled off, so only the player's own coffin is reachable
	private Map<GameObject, BarrowsBrother> findReachableSarcophagi(int[][] flags, Point start, int plane)
	{
		TunnelPathfinder pathfinder = new TunnelPathfinder(flags, Collections.emptySet());
		Map<GameObject, BarrowsBrother> reachable = new HashMap<>();
		sarcophagi.forEach((object, brother) ->
		{
			// Collision maps only cover the current floor
			if (object.getPlane() == plane && !pathfinder.findPath(start,
				tile -> isNextTo(tile, object.getSceneMinLocation(), object.getSceneMaxLocation())).isEmpty())
			{
				reachable.put(object, brother);
			}
		});
		return reachable;
	}

	private List<Point> findPathToChest(int[][] flags, Point start, int plane)
	{
		// Crypts are on a different floor from the tunnels, so their collision maps don't lead to the chest
		if (chest == null || doors.isEmpty() || chest.getPlane() != plane)
		{
			return Collections.emptyList();
		}

		doors.stream()
			.filter(this::isUnlocked)
			.map(door -> toScenePoint(door.getLocalLocation()))
			.forEach(unlockedDoorTiles::add);
		Point chestMin = chest.getSceneMinLocation();
		Point chestMax = chest.getSceneMaxLocation();

		return new TunnelPathfinder(flags, unlockedDoorTiles)
			.findPath(start, tile -> isNextTo(tile, chestMin, chestMax));
	}

	private boolean isUnlocked(TileObject door)
	{
		ObjectComposition definition = client.getObjectDefinition(door.getId());
		if (definition.getImpostorIds() != null)
		{
			definition = definition.getImpostor();
		}
		return definition != null && (definition.getId() == ObjectID.BARROWS_DOOR_UNLOCKED_L
			|| definition.getId() == ObjectID.BARROWS_DOOR_UNLOCKED_R);
	}

	private void reset()
	{
		sarcophagi.clear();
		reachableSarcophagi = Collections.emptyMap();
		doors.clear();
		unlockedDoorTiles.clear();
		chest = null;
		path = Collections.emptyList();
		clearRewardPlan();
	}

	static boolean isAtBarrows(Player player)
	{
		int regionId = player.getWorldLocation().getRegionID();
		return regionId == SURFACE_REGION_ID || regionId == UNDERGROUND_REGION_ID;
	}

	// Every tunnel door and state falls in this ID range
	static boolean isDoor(int objectId)
	{
		return objectId >= ObjectID.BARROWS_DOOR_INACTIVE_R && objectId <= ObjectID.BARROWS_DOOR_P_L;
	}

	static boolean isNextTo(Point tile, Point min, Point max)
	{
		return tile.getX() >= min.getX() - 1 && tile.getX() <= max.getX() + 1
			&& tile.getY() >= min.getY() - 1 && tile.getY() <= max.getY() + 1;
	}

	private static Point toScenePoint(LocalPoint localPoint)
	{
		return new Point(localPoint.getSceneX(), localPoint.getSceneY());
	}

	@Provides
	EzBarrowsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EzBarrowsConfig.class);
	}
}

